import type { WidgetType } from './feature-store.js';

export const ARCADE_CARD = `<article class="card"><h2>Chaos Wheel</h2><p>Der Auto-Pilot dreht alle 30 Minuten nur ausführbare Bot-Aktionen. Ein manueller Dreh kann zusätzlich eine Fortnite-Aufgabe oder Quest-Wahl ziehen.</p><div id="arcade-state" aria-live="polite"></div><div class="row"><button id="arcade-drop">Drop starten</button><button id="arcade-spin">Jetzt drehen</button><button id="arcade-finish-task" hidden>Aufgabe beenden</button><button id="arcade-stop" hidden>Automatik pausieren</button></div><details><summary>Automatik und Radfelder verwalten</summary><div class="row"><button data-arcade="petEnabled">Elio ein/aus</button><button data-arcade="dropsEnabled">Drops ein/aus</button><button data-arcade="wheelEnabled">Rad ein/aus</button><button data-arcade="wheelAutoPilotEnabled">Automatik ein/aus</button><label>Mindestabstand bei manuellem Dreh<select id="wheel-cooldown"><option value="300000">5 Minuten</option><option value="600000">10 Minuten</option><option value="900000">15 Minuten</option><option value="1800000">30 Minuten</option></select></label><button id="wheel-save-cooldown">Abstand speichern</button></div><p class="muted">„Automatisch“ bedeutet, der Bot führt alles aus. „Janniks Spielaufgabe“ wird angekündigt; der Bot kann Fortnite-Regeln nicht überwachen. Stimmt mit <code>!vote ZAHL</code> ab (zum Beispiel <code>!vote 1</code>); die Gewinnerquest startet nach dem Countdown.</p><div id="arcade-challenges"></div></details><p id="arcade-widget-status" class="muted" aria-live="polite">OBS-Linkstatus wird geprüft …</p></article>`;

export const ARCADE_REWARDS_CARD = `<article class="card"><h2>🎡 Community-Gewinner</h2><p class="muted">Ein Los pro Person, wenn sie in letzter Zeit im Chat aktiv war. VIP- und Mod-Status bringen keinen Vorteil.</p><p id="wheel-participant-status" aria-live="polite">Chat-Aktivität wird geprüft …</p><p id="wheel-last-winner" aria-live="polite"></p><div class="row"><label><input id="wheel-viewer-rewards" type="checkbox"> Zuschauer-Belohnungen aktivieren</label><label>Aktivitätsfenster<select id="wheel-activity-window"><option value="15">15 Minuten</option><option value="30">30 Minuten</option><option value="60">60 Minuten</option></select></label><label>XP für Gewinner<input id="wheel-winner-xp" type="number" min="1" max="100"></label><label>Community-Bonus pro Person<input id="wheel-community-xp" type="number" min="1" max="20"></label><label>Maximale Gewinne pro Stream<input id="wheel-max-rewards" type="number" min="1" max="50"></label></div><div class="row"><label><input id="wheel-personal-drop" type="checkbox"> Persönliche Mystery Drops erlauben</label><label><input id="wheel-chat-announcement" type="checkbox"> Gewinner im Chat nennen</label><label><input id="wheel-overlay-announcement" type="checkbox"> Gewinner im OBS-Overlay zeigen</label><button id="wheel-save-rewards">Einstellungen speichern</button></div><p class="muted">Belohnungsfelder kannst du unten bei „Automatik und Radfelder verwalten“ einzeln aktivieren. Neue Felder starten ausgeschaltet.</p></article>`;

export const ARCADE_REWARDS_SCRIPT = `async function loadWheelRewardSettings(){try{const d=await api('arcade'),s=d.settings,w=d.wheel;document.querySelector('#wheel-participant-status').textContent='Berechtigte aktive Chatteilnehmer im letzten '+s.viewerActivityWindowMinutes+' Minuten: '+w.activeViewerCount+' · davon mit XP-Spielraum: '+w.eligibleWinnerCount+' · Gewinnplätze in diesem Stream: '+w.prizeSlotsRemaining;document.querySelector('#wheel-last-winner').textContent=w.lastWinner?'Letzter Gewinner: @'+w.lastWinner.winnerName+(w.lastWinner.resultLabel?' · '+w.lastWinner.resultLabel:''):'Noch kein Zuschauergewinn gespeichert.';document.querySelector('#wheel-viewer-rewards').checked=s.viewerRewardsEnabled;document.querySelector('#wheel-activity-window').value=String(s.viewerActivityWindowMinutes);document.querySelector('#wheel-winner-xp').value=String(s.wheelWinnerXp);document.querySelector('#wheel-community-xp').value=String(s.wheelCommunityBonusXp);document.querySelector('#wheel-max-rewards').value=String(s.wheelMaxRewardsPerStream);document.querySelector('#wheel-personal-drop').checked=s.wheelPersonalMysteryDrop;document.querySelector('#wheel-chat-announcement').checked=s.wheelWinnerChatAnnouncement;document.querySelector('#wheel-overlay-announcement').checked=s.wheelWinnerOverlay}catch(e){document.querySelector('#wheel-participant-status').textContent=e.message}}document.querySelector('#wheel-save-rewards').onclick=async()=>{try{const d=await api('arcade'),s=d.settings;await api('arcade','POST',{settings:{...s,viewerRewardsEnabled:document.querySelector('#wheel-viewer-rewards').checked,viewerActivityWindowMinutes:Number(document.querySelector('#wheel-activity-window').value),wheelWinnerXp:Number(document.querySelector('#wheel-winner-xp').value),wheelCommunityBonusXp:Number(document.querySelector('#wheel-community-xp').value),wheelMaxRewardsPerStream:Number(document.querySelector('#wheel-max-rewards').value),wheelPersonalMysteryDrop:document.querySelector('#wheel-personal-drop').checked,wheelWinnerChatAnnouncement:document.querySelector('#wheel-chat-announcement').checked,wheelWinnerOverlay:document.querySelector('#wheel-overlay-announcement').checked}});show('Community-Gewinner-Einstellungen gespeichert.');loadWheelRewardSettings()}catch(e){show(e.message)}};loadWheelRewardSettings();setInterval(loadWheelRewardSettings,10000);`;
export const VAULT_CARD = `<article class="card"><h2>🔐 Community-Tresor</h2><p class="muted">Zuschauer raten gemeinsam einen geheimen, dreistelligen Code. Jeder gültige Tipp erhöht die Zahl der Rundenversuche; ein richtiger Code öffnet die Runde sofort, sonst endet sie nach der eingestellten Zeit. Pro Person gelten 3 Sekunden Abstand und höchstens 20 Tipps. Ab zwei gültigen Tipps greifen die eingestellten Teilnehmer-XP; Tageslimits können die tatsächliche Buchung reduzieren. Einzelne Hinweise sieht nur die angemeldete Person im Community-Portal.</p><div id="vault-status" aria-live="polite">Status wird geladen …</div><p id="vault-readiness" class="muted" aria-live="polite">Startbedingungen werden geprüft …</p><p id="vault-rules" class="muted" aria-live="polite"></p><form id="vault-settings"><label><input type="checkbox" name="enabled"> Tresor aktivieren</label><label><input type="checkbox" name="autoStart"> Automatisch starten, wenn Stream und Chat bereit sind</label><label>Spieldauer<select name="durationMinutes"><option value="2">2 Minuten</option><option value="3">3 Minuten</option><option value="5">5 Minuten</option><option value="10">10 Minuten</option></select></label><label>Mindestens aktive Zuschauer<input name="minActiveViewers" type="number" min="3" max="30" value="3"></label><label>Wartezeit zwischen Runden<input name="cooldownMinutes" type="number" min="10" max="180" value="30"> Minuten</label><label>XP pro qualifizierter Person<input name="participantXp" type="number" min="0" max="20" value="5"></label><label>Optionaler Finder-Bonus<input name="solverBonusXp" type="number" min="0" max="20" value="0"></label><button>Änderungen speichern</button></form><p class="muted">Automatik startet höchstens eine Runde pro Stunde und beachtet den gemeinsamen Cooldown, Mindestaktivität und andere laufende Spiele.</p><div class="row"><button id="vault-start" disabled>Runde starten</button><button id="vault-cancel" class="danger" disabled>Runde abbrechen</button></div><p id="vault-action-status" role="status" aria-live="polite"></p><h3>Letzte Runden</h3><div id="vault-history" aria-live="polite">Verlauf wird geladen …</div><p id="vault-widget-status" class="muted" aria-live="polite">OBS-Linkstatus wird geprüft …</p></article>`;
export const VAULT_SCRIPT = `let vaultBusy=false;async function vaultLoad(){try{const [d,widgets]=await Promise.all([api('vault'),api('widgets/status')]),f=document.querySelector('#vault-settings'),v=d.snapshot?.vault,ready=document.querySelector('#vault-readiness'),active=v?.status==='active';document.querySelector('#vault-widget-status').textContent=widgets.widgets?.vault?'Für den Tresor ist ein OBS-Link eingerichtet.':'Noch kein OBS-Link eingerichtet; Portal und Dashboard funktionieren trotzdem.';for(const k of ['enabled','autoStart'])f.elements.namedItem(k).checked=d.settings[k];for(const k of ['durationMinutes','minActiveViewers','cooldownMinutes','participantXp','solverBonusXp'])f.elements.namedItem(k).value=String(d.settings[k]);document.querySelector('#vault-status').textContent=active?'Tresor offen · '+v.attempts+' Tipps · noch '+Math.max(0,Math.ceil((v.endsAt-Date.now())/1000))+' Sekunden · Code bleibt geheim':v?.status==='opened'?'Tresor geöffnet'+(v.winnerName?' von '+v.winnerName:''):v?.status==='expired'?'Zeit abgelaufen · Code wurde aufgelöst':v?.status==='canceled'?'Runde abgebrochen':'Gerade keine Runde aktiv';document.querySelector('#vault-rules').textContent=d.settings.enabled?'Teilnahme im Twitch-Chat: !code 123 · mindestens 2 Tipps für Teilnehmer-XP bis zu '+d.settings.participantXp+' · Finder-Bonus bis zu '+d.settings.solverBonusXp+' · Cooldown zwischen Runden '+d.settings.cooldownMinutes+' Minuten. Tageslimit gilt.':'Tresor derzeit deaktiviert.';ready.textContent=d.readiness?.reason||'Startbedingungen werden beim Start geprüft.';document.querySelector('#vault-start').disabled=vaultBusy||active||!d.readiness?.canStart;document.querySelector('#vault-cancel').disabled=vaultBusy||!active;const history=document.querySelector('#vault-history');history.replaceChildren();for(const r of d.history||[]){const row=document.createElement('p');row.className='muted';const labels={opened:'Geöffnet',expired:'Zeit abgelaufen',canceled:'Abgebrochen',active:'Läuft'};row.textContent=new Date(r.startedAt).toLocaleString('de-DE')+' · '+labels[r.status]+' · '+r.attempts+' Tipps · '+r.awardedParticipants+' qualifizierte Personen · tatsächlich '+r.xpAwarded+' XP'+(r.winnerName?' · Finder: '+r.winnerName:'');history.append(row)}if(!history.children.length)history.textContent='Noch keine abgeschlossenen Tresorrunden.'}catch(e){document.querySelector('#vault-readiness').textContent='Status konnte nicht geladen werden: '+e.message;document.querySelector('#vault-start').disabled=true;document.querySelector('#vault-cancel').disabled=true}}async function vaultAction(action){if(vaultBusy)return;vaultBusy=true;const start=document.querySelector('#vault-start'),cancel=document.querySelector('#vault-cancel'),status=document.querySelector('#vault-action-status');start.disabled=true;cancel.disabled=true;status.textContent=action==='start'?'Tresor wird gestartet …':'Runde wird abgebrochen …';try{const r=await api('vault/action','POST',{action});status.textContent=r.message||'Aktion bestätigt.';await vaultLoad()}catch(e){status.textContent=e.message;await vaultLoad()}finally{vaultBusy=false;await vaultLoad()}}document.querySelector('#vault-settings').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=Object.fromEntries(new FormData(f));b.enabled=f.elements.namedItem('enabled').checked;b.autoStart=f.elements.namedItem('autoStart').checked;for(const k of ['durationMinutes','minActiveViewers','cooldownMinutes','participantXp','solverBonusXp'])b[k]=Number(b[k]);try{await api('vault/settings','POST',b);document.querySelector('#vault-action-status').textContent='Einstellungen gespeichert.';await vaultLoad()}catch(x){document.querySelector('#vault-action-status').textContent=x.message}};document.querySelector('#vault-start').onclick=()=>vaultAction('start');document.querySelector('#vault-cancel').onclick=()=>vaultAction('cancel');vaultLoad();setInterval(vaultLoad,5000);`;
export const ARCADE_SCRIPT = `async function arcadeLoad(){try{const d=await api('arcade'),state=document.querySelector('#arcade-state'),w=d.wheel;state.replaceChildren();for(const [label,on] of [['Elio',d.settings.petEnabled],['Mystery Drops',d.settings.dropsEnabled],['Glücksrad',d.settings.wheelEnabled],['Auto-Pilot',w.autoPilotEnabled]]){const p=document.createElement('p');p.textContent=label+': '+(on?'eingeschaltet':'ausgeschaltet');state.append(p)}if(d.pet){const p=document.createElement('p');const stages={egg:'Kätzchen',baby:'Jungkatze',young:'Erwachsene Katze',adult:'Erfahrene Katze',legendary:'Legendäre Community-Katze'};p.textContent='Pet: '+d.pet.name+' · '+(stages[d.pet.stage]||'Lebensphase unbekannt')+' · Level '+d.pet.level+' ('+d.pet.xp+' XP) · Hunger '+d.pet.hunger+' % · Energie '+d.pet.energy+' % · Zufriedenheit '+d.pet.happiness+' %'+(d.pet.paused?' · Pflegepause':'');state.append(p)}const active=document.createElement('p');active.textContent=w.activeAction?'Aktuell: '+w.activeAction.title+(w.activeAction.endsAt?' · noch '+Math.max(0,Math.ceil((w.activeAction.endsAt-Date.now())/1000))+' Sek.':''):'Aktuell läuft keine Rad-Aktion';state.append(active);const next=document.createElement('p');next.textContent='Auto-Pilot: '+w.reason+(w.nextAutoSpinAt?' · nächster möglicher Dreh '+new Date(w.nextAutoSpinAt).toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'}):'');state.append(next);const list=document.querySelector('#arcade-challenges');list.replaceChildren();for(const entry of (w.wheelFields||[...w.entries,...(w.taskEntries||[])])){const row=document.createElement('div');row.className='wheel-field';const text=document.createElement('span');text.textContent=entry.title+' · '+entry.description+' · '+(entry.kind==='automatic'?'Automatisch':entry.kind==='viewer-prize'?'Zuschauer-Ergebnis':'Janniks Spielaufgabe')+' · '+entry.probabilityLabel+' '+entry.probability+' %';const toggle=document.createElement('input');toggle.type='checkbox';toggle.checked=entry.active;toggle.disabled=entry.wheelKey==='gaming_quiz';toggle.setAttribute('aria-label',entry.title+' aktivieren');toggle.onchange=async()=>{try{await api('arcade','POST',{action:'wheel-field',id:entry.id,active:toggle.checked,weight:entry.weight});show('Radfeld gespeichert.');arcadeLoad()}catch(e){toggle.checked=!toggle.checked;show(e.message)}};row.append(text,toggle);list.append(row)}for(const entry of w.unavailable||[]){const row=document.createElement('p');row.textContent='Vorübergehend nicht verfügbar: '+entry.title+' · '+entry.reason;list.append(row)}for(const b of document.querySelectorAll('[data-arcade]')){const labels={petEnabled:'Elio',dropsEnabled:'Mystery Drops',wheelEnabled:'Glücksrad',wheelAutoPilotEnabled:'Auto-Pilot'},on=b.dataset.arcade==='wheelAutoPilotEnabled'?w.autoPilotEnabled:d.settings[b.dataset.arcade];b.textContent=(on?'Ausschalten: ':'Einschalten: ')+labels[b.dataset.arcade];b.onclick=async()=>{const settings={...d.settings,[b.dataset.arcade]:!on};await api('arcade','POST',{settings});show('Einstellung gespeichert.');arcadeLoad()}}const spin=document.querySelector('#arcade-spin');spin.disabled=!w.canManualSpin;spin.title=w.canManualSpin?'Startet einen manuellen Dreh einschließlich gegebenenfalls Janniks Spielaufgabe.':w.reason;document.querySelector('#arcade-finish-task').hidden=!(w.activeAction&&w.activeAction.actionType==='manual_challenge');document.querySelector('#wheel-cooldown').value=String(d.settings.wheelCooldownMs)}catch(e){show(e.message)}}document.querySelector('#arcade-drop').onclick=async()=>{try{const x=await api('arcade','POST',{action:'start-drop'});show(x.message);arcadeLoad()}catch(e){show(e.message)}};document.querySelector('#arcade-spin').onclick=async()=>{try{const x=await api('arcade','POST',{action:'spin'});show(x.message);arcadeLoad()}catch(e){show(e.message)}};document.querySelector('#arcade-finish-task').onclick=async()=>{try{const x=await api('arcade','POST',{action:'finish-task'});show(x.message);arcadeLoad()}catch(e){show(e.message)}};document.querySelector('#arcade-stop').onclick=async()=>{if(!confirm('Automatik pausieren? Ein laufender Drop wird sicher zu Ende gespielt.'))return;try{const x=await api('arcade','POST',{action:'emergency-stop'});show(x.message);arcadeLoad()}catch(e){show(e.message)}};document.querySelector('#wheel-save-cooldown').onclick=async()=>{try{const d=await api('arcade'),settings={...d.settings,wheelCooldownMs:Number(document.querySelector('#wheel-cooldown').value)};await api('arcade','POST',{settings});show('Abstand gespeichert.');arcadeLoad()}catch(e){show(e.message)}};arcadeLoad();setInterval(arcadeLoad,5000);`;

export const QUEST_POLL_CARD = `<article class="card"><h2>1. Neue Vorschläge prüfen</h2><p class="muted">Zuschauer reichen Aufgaben ein. Gib faire Vorschläge frei oder lehne sie ab. Erst nach deiner Freigabe können sie gestartet werden.</p><p id="quest-summary" class="muted" aria-live="polite"></p><details><summary>Suche und Filter</summary><div class="row"><select id="quest-filter" aria-label="Aufgaben filtern"><option value="all">Alle Schritte</option><option value="pending">Neue Vorschläge</option><option value="approved">Freigegeben</option><option value="active">Läuft gerade</option><option value="completed">Abgeschlossen</option><option value="failed">Nicht geschafft</option><option value="rejected">Abgelehnt</option><option value="canceled">Abgebrochen</option></select><input id="quest-search" placeholder="Aufgabe oder Name suchen" aria-label="Aufgabe oder Name suchen"><button id="quest-refresh" type="button">Aktualisieren</button></div></details><div id="quest-queue" class="quest-flow"><section><h3>Neue Vorschläge</h3><div id="quest-pending" class="quest-list"></div></section><section><h3>Freigegebene Aufgaben</h3><div id="quest-approved" class="quest-list"></div></section><section><h3>Aktuelle Aufgabe</h3><div id="quest-active" class="quest-list"></div></section><details><summary>Abgeschlossene oder abgelehnte Aufgaben</summary><div id="quest-history" class="quest-list"></div></details></div><details><summary>Eine eigene Community-Aufgabe vorschlagen</summary><form id="dashboard-quest-form"><label>Aufgabe<input name="title" maxlength="180" minlength="3" placeholder="Zum Beispiel: Schaffe eine Runde ohne Schaden" required></label><label>Spiel (optional)<input name="game" maxlength="80" placeholder="Spielname"></label><button>Vorschlag einreichen</button></form><p class="muted">Der Vorschlag ist zunächst nur intern sichtbar.</p></details></article>
<article class="card"><h2>2. Optional abstimmen lassen</h2><p class="muted">Wähle zwei bis fünf freigegebene Aufgaben. Nach der Abstimmung musst du den Gewinner noch ausdrücklich starten.</p><form id="quest-poll-form"><div id="quest-poll-options"></div><label>Wie lange darf der Chat abstimmen?<span><input name="durationSeconds" type="number" min="10" max="3600" value="60" aria-label="Dauer der Quest-Abstimmung in Sekunden"> Sekunden</span></label><button>Abstimmung starten</button></form></article>
<article class="card"><h2>Live-Abstimmungen</h2><p class="muted">Stelle eine harmlose Stream-Frage. Zuschauer stimmen im Community-Portal oder im Chat mit <code>!vote 1</code> ab. Pro Twitch-Konto zählt eine Stimme.</p><form id="poll-form"><label>Vorlage<select id="poll-template"><option value="custom">Eigene Frage</option><option value="weapon">Welche Waffe soll Jannik benutzen?</option><option value="wheel">Soll das Chaos Wheel gedreht werden?</option><option value="quest">Welche Community-Quest kommt als Nächstes?</option><option value="strategy">Welche Spielstrategie soll Jannik ausprobieren?</option></select></label><label>Frage<input name="question" maxlength="180" minlength="3" placeholder="Was soll die Community entscheiden?" required></label><label>Antworten<textarea name="options" placeholder="Eine Antwort pro Zeile (2–5)" required></textarea></label><label>Abstimmungsdauer<select name="durationSeconds"><option value="30">30 Sekunden</option><option value="60" selected>60 Sekunden</option><option value="90">90 Sekunden</option><option value="120">2 Minuten</option><option value="180">3 Minuten</option></select></label><button>Abstimmung starten</button></form><div id="poll-current"></div><div id="poll-history"></div></article>
<article class="card"><h2>Overlay-Vorschau</h2><p class="muted">Sichere Textvorschau des aktuellen Zustands. Die OBS-Widgets bleiben transparent und werden live aktualisiert.</p><div id="quest-overlay-preview" class="preview-widget">Noch keine aktive Quest.</div><div id="poll-overlay-preview" class="preview-widget">Keine aktuelle Umfrage.</div></article>
<article class="card"><h2>OBS-Widgets</h2><p class="muted">Je Widget ein eng begrenztes Lesetoken. Erneuern widerruft die vorige URL; das Token wird nur einmal angezeigt.</p><div class="row"><button data-widget="quest" class="widget-rotate">Quest-URL erneuern</button><button data-widget="poll" class="widget-rotate">Umfrage-URL erneuern</button><button data-widget="imposter" class="widget-rotate">Imposter-URL erneuern</button><button data-widget="detective" class="widget-rotate">Detektiv-URL erneuern</button><button data-widget="pet" class="widget-rotate">Pet-URL erneuern</button><button data-widget="drop" class="widget-rotate">Drop-URL erneuern</button><button data-widget="wheel" class="widget-rotate">Wheel-URL erneuern</button></div><div class="row"><button data-widget="quest" class="widget-revoke">Quest-URL widerrufen</button><button data-widget="poll" class="widget-revoke">Umfrage-URL widerrufen</button><button data-widget="imposter" class="widget-revoke">Imposter-URL widerrufen</button><button data-widget="detective" class="widget-revoke">Detektiv-URL widerrufen</button><button data-widget="pet" class="widget-revoke">Pet-URL widerrufen</button><button data-widget="drop" class="widget-revoke">Drop-URL widerrufen</button><button data-widget="wheel" class="widget-revoke">Wheel-URL widerrufen</button></div><input id="widget-url" readonly aria-label="Einmalig angezeigte OBS-Widget-URL" placeholder="Nach Erneuerung wird die URL hier angezeigt"><button id="widget-copy">URL kopieren</button><p class="muted">Die Widget-URL gewährt weder Dashboard-Zugriff noch Schreibrechte. Behandle sie wie ein geheimes Passwort.</p></article>`;

export const QUEST_POLL_SCRIPT = String.raw`
const questRoot=document.querySelector('#quest-queue'),questFilter=document.querySelector('#quest-filter'),questSearch=document.querySelector('#quest-search');
function preview(root,text,detail){root.replaceChildren();const heading=document.createElement('strong'),body=document.createElement('p'),small=document.createElement('small');heading.textContent='LIVE-VORSCHAU';body.textContent=text;small.textContent=detail;root.append(heading,body,small)}
async function refreshQuests(){try{const d=await api('quests?status='+encodeURIComponent(questFilter.value)+'&q='+encodeURIComponent(questSearch.value)),summary=document.querySelector('#quest-summary'),labels={pending:'Neue Vorschläge',approved:'Freigegeben',active:'Aktuell',completed:'Abgeschlossen',failed:'Nicht geschafft',rejected:'Abgelehnt',canceled:'Abgebrochen'};summary.textContent=Object.entries(d.summary).map(([k,v])=>(labels[k]||k)+': '+v).join(' · ')||'Noch keine Aufgaben';preview(document.querySelector('#quest-overlay-preview'),d.active?'LIVE-AUFGABE · '+d.active.title:'Noch keine aktive Aufgabe.',d.active?'Die Aufgabe ist freigegeben und läuft.':'Das Widget bleibt ausgeblendet.');const lists={pending:document.querySelector('#quest-pending'),approved:document.querySelector('#quest-approved'),active:document.querySelector('#quest-active'),history:document.querySelector('#quest-history')};for(const list of Object.values(lists))list.replaceChildren();for(const q of d.quests){const row=document.createElement('article'),title=document.createElement('strong'),meta=document.createElement('p');row.className='quest-row';title.textContent=q.title;meta.className='muted';meta.textContent='Vorgeschlagen von '+q.displayName+(q.game?' · '+q.game:'');row.append(title,meta);const addAction=(caption,action,kind='')=>{const b=document.createElement('button');b.type='button';b.textContent=caption;if(kind)b.className=kind;b.onclick=async()=>{b.disabled=true;try{await api('quests/action','POST',{id:q.id,action});show('Aufgabe aktualisiert.');await refreshQuests();await refreshQuestChoices()}catch(e){b.disabled=false;show(e.message)}};row.append(b)};const edit=document.createElement('button');edit.type='button';edit.textContent='Bearbeiten';edit.onclick=async()=>{const title=window.prompt('Aufgabe bearbeiten',q.title);if(title===null)return;const game=window.prompt('Spiel (optional)',q.game||'');if(game===null)return;try{await api('quests/edit','POST',{id:q.id,title,game});show('Vorschlag geändert.');await refreshQuests();await refreshQuestChoices()}catch(e){show(e.message)}};let list=lists.history;if(q.status==='pending'){list=lists.pending;addAction('Freigeben','approve');addAction('Ablehnen','reject','secondary');row.append(edit)}else if(q.status==='approved'){list=lists.approved;addAction(q.queuedNext?'Als Nächstes markiert':'Als Nächstes vormerken','select','secondary');addAction('Aufgabe starten','start');addAction('Ablehnen','reject','secondary');row.append(edit)}else if(q.status==='active'){list=lists.active;addAction('Als geschafft abschließen','complete');addAction('Als nicht geschafft markieren','fail','secondary');addAction('Abbrechen','skip','danger')}list.append(row)}for(const [key,list] of Object.entries(lists)){if(!list.children.length){const empty=document.createElement('p');empty.className='muted';empty.textContent=key==='pending'?'Noch keine neuen Vorschläge.':key==='approved'?'Noch keine freigegebenen Aufgaben.':key==='active'?'Gerade läuft keine Aufgabe.':'Hier erscheinen Aufgaben nach ihrem Abschluss.';list.append(empty)}}}catch(e){show(e.message)}}
async function refreshQuestChoices(){try{const d=await api('quests?status=approved'),root=document.querySelector('#quest-poll-options');root.replaceChildren();for(const q of d.quests){const label=document.createElement('label'),box=document.createElement('input');box.type='checkbox';box.value=q.id;label.append(box,' '+q.title+' · '+q.displayName);root.append(label)}}catch(e){show(e.message)}}
async function renderPolls(){try{const d=await api('polls'),root=document.querySelector('#poll-current'),history=document.querySelector('#poll-history');root.replaceChildren();history.replaceChildren();if(d.active){const p=d.active,title=document.createElement('h3');title.textContent=(p.status==='active'?'LIVE · ':'ERGEBNIS · ')+p.question;root.append(title);preview(document.querySelector('#poll-overlay-preview'),p.question,p.options.map((o,i)=>(i+1)+'. '+o.label+' · '+o.votes+' ('+o.percent+'%)').join('   |   '));for(let i=0;i<p.options.length;i++){const o=p.options[i],line=document.createElement('p');line.textContent=(i+1)+'. '+o.label+' — '+o.votes+' Stimmen ('+o.percent+'%)';root.append(line)}const count=document.createElement('p');count.textContent='Stimmen: '+p.totalVotes+(p.status==='active'?' · endet '+new Date(p.endsAt).toLocaleTimeString():'');root.append(count);if(p.status==='active'){const end=document.createElement('button');end.textContent='Umfrage jetzt beenden';end.onclick=async()=>{try{await api('polls/action','POST',{id:p.id,action:'end'});renderPolls()}catch(e){show(e.message)}};root.append(end)}if(p.status==='ended'&&p.type==='quest'){if(p.tied||p.winnerOption===null){const select=document.createElement('select');select.setAttribute('aria-label','Gewinnerquest manuell auswählen');for(let i=0;i<p.options.length;i++){const op=document.createElement('option');op.value=String(i+1);op.textContent=(i+1)+'. '+p.options[i].label;select.append(op)}const choose=document.createElement('button');choose.textContent='Quest-Gewinner festlegen';choose.onclick=async()=>{try{await api('polls/action','POST',{id:p.id,action:'winner',option:Number(select.value)});renderPolls()}catch(e){show(e.message)}};root.append(select,choose)}const start=document.createElement('button');start.textContent='Gewinnerquest ausdrücklich starten';start.onclick=async()=>{try{await api('polls/action','POST',{id:p.id,action:'start-quest'});show('Quest gestartet.');refreshQuests();renderPolls()}catch(e){show(e.message)}};root.append(start)}}else preview(document.querySelector('#poll-overlay-preview'),'Keine aktuelle Umfrage.','Das Widget bleibt ausgeblendet.');for(const p of d.history){const line=document.createElement('p');line.textContent=new Date(p.startsAt).toLocaleString()+' · '+p.question+' · '+p.totalVotes+' Stimmen'+(p.tied?' · Gleichstand':'');history.append(line)}}catch(e){show(e.message)}}
document.querySelector('#quest-filter').onchange=refreshQuests;document.querySelector('#quest-search').oninput=()=>{clearTimeout(window.questSearchTimer);window.questSearchTimer=setTimeout(refreshQuests,250)};document.querySelector('#quest-refresh').onclick=refreshQuests;
document.querySelector('#dashboard-quest-form').onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.currentTarget));try{await api('quests','POST',v);show('Interner Questvorschlag angelegt.');e.currentTarget.reset();refreshQuests()}catch(x){show(x.message)}};
document.querySelector('#quest-poll-form').onsubmit=async e=>{e.preventDefault();const ids=Array.from(document.querySelectorAll('#quest-poll-options input:checked')).map(x=>x.value),seconds=Number(e.currentTarget.elements.namedItem('durationSeconds').value);try{await api('polls/quest-vote','POST',{questIds:ids,durationSeconds:seconds});show('Quest-Abstimmung gestartet.');refreshQuestChoices();renderPolls()}catch(x){show(x.message)}};
const pollTemplates={weapon:['Welche Waffe soll Jannik benutzen?',['Lieblingswaffe','Zufallswaffe']],wheel:['Soll das Chaos Wheel gedreht werden?',['Ja, jetzt drehen','Lieber später']],quest:['Welche Community-Quest kommt als Nächstes?',['Quest 1','Quest 2']],strategy:['Welche Spielstrategie soll Jannik ausprobieren?',['Sicher spielen','Volles Risiko']]};document.querySelector('#poll-template').onchange=e=>{const t=pollTemplates[e.currentTarget.value];if(t){document.querySelector('#poll-form [name="question"]').value=t[0];document.querySelector('#poll-form [name="options"]').value=t[1].join('\n')}};
document.querySelector('#poll-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),options=String(f.get('options')||'').split(/\r?\n/u).map(x=>x.trim()).filter(Boolean);try{await api('polls','POST',{question:f.get('question'),options,durationSeconds:Number(f.get('durationSeconds'))});show('Abstimmung gestartet.');e.currentTarget.reset();renderPolls()}catch(x){show(x.message)}};
document.querySelectorAll('.widget-rotate').forEach(b=>b.onclick=async()=>{try{const d=await api('widgets/token','POST',{type:b.dataset.widget,action:'rotate'});document.querySelector('#widget-url').value=d.url;show('Neue, alte URL widerrufende Widget-URL erstellt.')}catch(e){show(e.message)}});document.querySelectorAll('.widget-revoke').forEach(b=>b.onclick=async()=>{try{await api('widgets/token','POST',{type:b.dataset.widget,action:'revoke'});document.querySelector('#widget-url').value='';show('Widget-Zugriff widerrufen.')}catch(e){show(e.message)}});document.querySelector('#widget-copy').onclick=async()=>{const field=document.querySelector('#widget-url');if(!field.value){show('Bitte erst eine Widget-URL erstellen.');return}try{await navigator.clipboard.writeText(field.value);show('Widget-URL kopiert.')}catch{field.select();show('URL markieren und manuell kopieren.')}};
refreshQuests();refreshQuestChoices();renderPolls();setInterval(()=>{refreshQuests();renderPolls()},5000);
api('settings').then(s=>{const seconds=Math.round((s.poll_settings?.durationMs||60000)/1000);document.querySelector('#poll-form').elements.namedItem('durationSeconds').value=String([30,60,90,120,180].includes(seconds)?seconds:60);document.querySelector('#quest-poll-form').elements.namedItem('durationSeconds').value=String(seconds)}).catch(e=>show(e.message));
`;

export function communityWidgetHtml(type: WidgetType, nonce: string, configuredFontSize: number, theme: string): string {
  if(type==='vault')return vaultWidgetHtml(nonce);
  if(type==='pet'||type==='drop'||type==='wheel')return arcadeWidgetHtml(type,nonce);
  if(type==='imposter'||type==='detective')return miniGameWidgetHtml(type,nonce);
  const fontSize = Number.isInteger(configuredFontSize) ? Math.max(22, Math.min(54, configuredFontSize)) : 34;
  const accent = theme === 'halloween' ? '#ff9b3d' : '#b69cff';
  const title = type === 'quest' ? 'LIVE-QUEST' : 'LIVE-UMFRAGE';
  const content = type === 'quest' ? `
<main id="card" class="card" hidden aria-live="polite"><header><strong>LIVE-QUEST</strong><span id="state"></span></header><h1 id="title"></h1><p id="game"></p><footer id="submitter"></footer><p id="countdown"></p></main>
<script nonce="${nonce}">
const card=document.querySelector('#card');let lastStatus='',hideTimer,expiryAt=0;function updateCountdown(){const left=expiryAt?Math.max(0,Math.ceil((expiryAt-Date.now())/1000)):0;document.querySelector('#countdown').textContent=left?'Noch '+Math.floor(left/60)+':'+String(left%60).padStart(2,'0'):''}function render(d){const q=d&&d.quest;if(!d||!d.visible||!q){card.classList.remove('show');clearTimeout(hideTimer);hideTimer=setTimeout(()=>card.hidden=true,450);expiryAt=0;updateCountdown();return}card.hidden=false;requestAnimationFrame(()=>card.classList.add('show'));document.querySelector('#title').textContent=q.title||'';document.querySelector('#game').textContent=q.game?'🎮 '+q.game:'';document.querySelector('#submitter').textContent=q.displayName?'Vorschlag von '+q.displayName:'';const status=document.querySelector('#state');status.textContent=q.status==='active'?'AKTIV':q.status==='completed'?'GESCHAFFT!':q.status==='failed'?'NICHT GESCHAFFT':'ÜBERSPRUNGEN';card.dataset.result=q.status;expiryAt=Number(q.expiresAt)||0;updateCountdown();if(q.status!==lastStatus&&(q.status==='completed'||q.status==='failed')){card.classList.remove('success','failure');requestAnimationFrame(()=>card.classList.add(q.status==='completed'?'success':'failure'));clearTimeout(hideTimer);hideTimer=setTimeout(()=>{card.classList.remove('show');setTimeout(()=>card.hidden=true,450)},7000)}lastStatus=q.status}async function refresh(){try{const r=await fetch('/widgets/api/quest'+location.search,{cache:'no-store'});if(r.ok)render(await r.json())}catch{}}const events=new EventSource('/widgets/stream/quest'+location.search);events.addEventListener('snapshot',e=>{try{render(JSON.parse(e.data))}catch{}});events.onopen=refresh;window.addEventListener('online',refresh);refresh();setInterval(refresh,30000);setInterval(updateCountdown,1000);
</script>` : `
<main id="card" class="card poll" hidden aria-live="polite"><header><strong>LIVE-UMFRAGE</strong><span id="timer"></span></header><h1 id="question"></h1><div id="options"></div><p id="result"></p></main>
<script nonce="${nonce}">
const card=document.querySelector('#card');let hideTimer,pollEnd=0,pollActive=false;function updateTimer(){const seconds=pollActive?Math.max(0,Math.ceil((pollEnd-Date.now())/1000)):0;document.querySelector('#timer').textContent=pollActive?'Noch '+Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0'):'BEENDET'}function render(d){const p=d&&d.poll;if(!d||!d.visible||!p){card.classList.remove('show');clearTimeout(hideTimer);hideTimer=setTimeout(()=>card.hidden=true,450);pollActive=false;updateTimer();return}card.hidden=false;requestAnimationFrame(()=>card.classList.add('show'));document.querySelector('#question').textContent=p.question||'';const list=document.querySelector('#options');list.replaceChildren();for(let i=0;i<p.options.length;i++){const o=p.options[i],line=document.createElement('section'),label=document.createElement('div'),track=document.createElement('div'),bar=document.createElement('div');line.className='option';label.className='option-label';label.textContent=(i+1)+'. '+o.label+' · '+o.votes+' ('+o.percent+'%)';track.className='track';bar.className='bar';bar.style.width=Math.max(0,Math.min(100,o.percent))+'%';track.append(bar);line.append(label,track);list.append(line)}pollEnd=Number(p.endsAt)||0;pollActive=p.status==='active';updateTimer();const outcome=document.querySelector('#result');outcome.textContent=p.status==='ended'?(p.tied?'Gleichstand – Jannik entscheidet.':p.winnerOption===null?'Keine Stimmen.':'Gewinner: '+(p.options[p.winnerOption]||{}).label):'Stimme im Chat ab: !vote 1–'+p.options.length;if(p.status==='ended'){clearTimeout(hideTimer);hideTimer=setTimeout(()=>{card.classList.remove('show');setTimeout(()=>card.hidden=true,450)},9000)}}async function refresh(){try{const r=await fetch('/widgets/api/poll'+location.search,{cache:'no-store'});if(r.ok)render(await r.json())}catch{}}const events=new EventSource('/widgets/stream/poll'+location.search);events.addEventListener('snapshot',e=>{try{render(JSON.parse(e.data))}catch{}});events.onopen=refresh;window.addEventListener('online',refresh);refresh();setInterval(refresh,30000);setInterval(updateTimer,1000);
</script>`;
  return `<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="no-referrer"><title>${title}</title><style nonce="${nonce}">
:root{color-scheme:dark;--accent:${accent};--size:${fontSize}px;font-family:system-ui,sans-serif}*{box-sizing:border-box}html,body{margin:0;width:100%;min-height:100%;background:transparent;color:#f7f7fb}body{padding:18px}.card{width:min(100%,1000px);border:1px solid color-mix(in srgb,var(--accent),white 20%);border-left:7px solid var(--accent);border-radius:20px;padding:clamp(18px,2.2vw,34px);background:linear-gradient(130deg,rgba(19,22,32,.94),rgba(32,28,45,.82));box-shadow:0 12px 38px rgba(0,0,0,.45),0 0 24px color-mix(in srgb,var(--accent),transparent 76%);backdrop-filter:blur(14px);font-size:var(--size);opacity:0;transform:translateY(14px) scale(.985);transition:opacity .4s ease,transform .4s ease,box-shadow .4s ease}.card.show{opacity:1;transform:translateY(0) scale(1)}header{display:flex;justify-content:space-between;gap:12px;align-items:center;color:var(--accent);font-size:.67em;letter-spacing:.12em;font-weight:800}header span{color:#f3edfF}h1{font-size:1em;line-height:1.22;margin:.7em 0 .45em;text-shadow:0 2px 8px #000;overflow-wrap:anywhere}p{font-size:.66em;color:#d6d7e1;margin:.5em 0 0}footer{font-size:.62em;color:#b6b8c6}.option{margin:.8em 0}.option-label{font-size:.62em;margin-bottom:.26em;overflow-wrap:anywhere}.track{height:.36em;background:rgba(255,255,255,.13);border-radius:99px;overflow:hidden}.bar{height:100%;border-radius:inherit;background:linear-gradient(90deg,var(--accent),#ece4ff);transition:width .45s ease}.success{box-shadow:0 0 44px rgba(76,230,151,.62)}.failure{box-shadow:0 0 44px rgba(255,113,113,.56)}[hidden]{display:none!important}@media(max-width:600px){body{padding:10px}.card{border-radius:14px}}@media(prefers-reduced-motion:reduce){*,*::before,*::after{transition:none!important;animation:none!important;scroll-behavior:auto!important}}
</style></head><body>${content}</body></html>`;
}

export type WheelSegmentInput = { id: string; title: string; weight: number };
export type WheelSegment = WheelSegmentInput & { startAngle: number; endAngle: number; centerAngle: number };

/** Proportional segment geometry; the backend weight remains the source of probability. */
export function wheelSegments(fields: WheelSegmentInput[]): WheelSegment[] {
  const usable=fields.filter(field=>Number.isFinite(field.weight)&&field.weight>0);
  const total=usable.reduce((sum,field)=>sum+field.weight,0);
  if(!total)return [];
  let angle=-90;
  return usable.map(field=>{const startAngle=angle;angle+=360*field.weight/total;return {...field,startAngle,endAngle:angle,centerAngle:(startAngle+angle)/2};});
}

function vaultWidgetHtml(nonce:string):string {
  return `<!doctype html><html lang="de"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="no-referrer"><title>COMMUNITY-TRESOR</title><style nonce="${nonce}">html,body{margin:0;background:transparent;color:#fff;font:700 clamp(18px,3vw,38px) system-ui}.card{padding:20px 26px;border:2px solid #c6a8ff;border-radius:22px;background:linear-gradient(135deg,#171522ed,#302244e8);box-shadow:0 8px 30px #0008;width:min(94vw,760px)}header{color:#d2b6ff;font-size:.62em;letter-spacing:.1em}h1{font-size:1em;margin:.5em 0}p{font-size:.62em;color:#e2d7f5;margin:.35em 0}[hidden]{display:none!important}</style><main id="root" class="card" hidden><header>🔐 COMMUNITY-TRESOR</header><h1 id="state"></h1><p id="timer"></p><p id="attempts"></p><p id="hint"></p><p id="result"></p></main><script nonce="${nonce}">const root=document.querySelector('#root');function render(x){const v=x?.vault;if(!x?.visible||!v){root.hidden=true;return}root.hidden=false;root.dataset.ends=String(v.endsAt||0);document.querySelector('#state').textContent=v.status==='active'?'Der Tresor ist geschlossen':v.status==='opened'?'Der Tresor ist offen':'Die Runde ist beendet';document.querySelector('#timer').textContent=v.status==='active'?'Noch '+Math.max(0,Math.ceil((v.endsAt-Date.now())/1000))+' Sekunden':'';document.querySelector('#attempts').textContent=v.status==='active'?v.attempts+' gemeinsame Versuche':'';document.querySelector('#hint').textContent=v.lastHint?'Letzter Hinweis: '+v.lastHint:'';document.querySelector('#result').textContent=v.status==='opened'?(v.winnerName?'Geknackt von '+v.winnerName:'Code geknackt!'):v.status==='expired'?(v.resultCode?'Code '+v.resultCode:'Zeit abgelaufen'):''}function refresh(){fetch('/widgets/api/vault'+location.search,{cache:'no-store'}).then(r=>r.json()).then(render).catch(()=>{})}const es=new EventSource('/widgets/stream/vault'+location.search);es.addEventListener('snapshot',e=>{try{render(JSON.parse(e.data))}catch{}});es.onopen=refresh;refresh();setInterval(refresh,30000);setInterval(()=>{const n=document.querySelector('#timer');if(!root.hidden&&n.textContent)n.textContent='Noch '+Math.max(0,Math.ceil((Number(root.dataset.ends||0)-Date.now())/1000))+' Sekunden'},1000);</script></html>`;
}

function miniGameWidgetHtml(type:'imposter'|'detective',nonce:string):string{
  const imposter=type==='imposter';
  const title=imposter?'CHAT-IMPOSTER':'WER HAT DAS GESCHRIEBEN?';
  const markup=imposter?'<header><strong>CHAT-IMPOSTER</strong><span id="phase"></span></header><h1 id="summary"></h1><p id="detail"></p>':'<header><strong>WER HAT DAS GESCHRIEBEN?</strong><span id="timer"></span></header><blockquote id="quote"></blockquote><p id="detail"></p>';
  const script=imposter?`const g=x.game;if(!x.visible||!g){root.hidden=true;return}root.hidden=false;document.querySelector('#phase').textContent=g.phase==='registration'?'ANMELDUNG':g.phase==='playing'?'SPIEL LÄUFT':g.phase==='voting'?'ABSTIMMUNG':g.phase==='results'?'AUFLÖSUNG':g.phase.toUpperCase();document.querySelector('#summary').textContent=g.phase==='results'&&g.result?(g.result.caught?'Der Imposter wurde enttarnt!':'Der Imposter hat gewonnen: @'+g.result.imposterName):g.participants+' Teilnehmende · '+g.votes+' Stimmen';document.querySelector('#detail').textContent=g.phase==='results'&&g.result?'Geheime Regel: '+g.result.rule+' · '+g.result.votes+' Stimmen':g.endsAt?'Noch '+Math.max(0,Math.ceil((g.endsAt-Date.now())/1000))+' Sekunden':'';`:`const g=x.game;if(!x.visible||!g){root.hidden=true;return}root.hidden=false;document.querySelector('#quote').textContent='„'+g.text+'“';const r=g.result;document.querySelector('#detail').textContent=r?'Auflösung: @'+r.authorName+' · '+r.winners.length+' richtige Tipps':g.guesses+' Tipps abgegeben · noch '+Math.max(0,Math.ceil((g.endsAt-Date.now())/1000))+' Sekunden';document.querySelector('#timer').textContent=r?'AUFGELÖST':'LIVE';`;
  return `<!doctype html><html lang="de"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="no-referrer"><title>${title}</title><style nonce="${nonce}">html,body{margin:0;background:transparent;color:#f7f7fb;font:700 clamp(18px,3vw,38px) system-ui}.card{box-sizing:border-box;width:min(94vw,900px);padding:22px 28px;border:2px solid #ba86ff;border-radius:22px;background:linear-gradient(130deg,#131620ed,#302239e8);box-shadow:0 8px 30px #0008;animation:pop .35s ease}header{display:flex;justify-content:space-between;color:#d2b6ff;font-size:.55em;letter-spacing:.1em}h1{font-size:.9em;margin:.6em 0}blockquote{font-size:.95em;line-height:1.3;margin:.6em 0;overflow-wrap:anywhere}p{font-size:.58em;color:#d4d4df;margin:.4em 0}[hidden]{display:none!important}@keyframes pop{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}@media(prefers-reduced-motion:reduce){*{animation:none!important}}</style><main id="root" class="card" hidden>${markup}</main><script nonce="${nonce}">const root=document.querySelector('#root');function render(x){${script}}function refresh(){fetch('/widgets/api/${type}'+location.search,{cache:'no-store'}).then(r=>r.json()).then(render).catch(()=>{})}const es=new EventSource('/widgets/stream/${type}'+location.search);es.addEventListener('snapshot',e=>{try{render(JSON.parse(e.data))}catch{}});es.onopen=refresh;refresh();setInterval(refresh,1000);</script></html>`;
}

function arcadeWidgetHtml(type:'pet'|'drop'|'wheel',nonce:string):string {
  if(type==='wheel')return wheelWidgetHtml(nonce);
  const title=type==='pet'?'ELIO · COMMUNITY-KATZE':type==='drop'?'MYSTERY DROP':'CHAOS WHEEL';
  const markup=type==='pet'?`<div class="cat" aria-hidden="true">🐱</div><h1 id="name"></h1><p id="info"></p><p id="prank-banner" hidden></p><p id="personality-hint" hidden></p>`:type==='drop'?`<div class="chest">🎁</div><h1 id="title"></h1><p id="info"></p>`:`<div class="wheel">🎡</div><h1 id="title"></h1><p id="info"></p>`;
  const script=type==='pet'?`const d=x.pet;if(!x.visible||!d){root.hidden=true;return}root.hidden=false;document.querySelector('#name').textContent=d.name;document.querySelector('#info').textContent=(d.moodLabel||'🐾 Entspannt')+' · '+(d.stageLabel||d.stage)+' · Level '+d.level+' · Zufriedenheit '+d.happiness+'%';root.dataset.anim=d.animation;const banner=document.querySelector('#prank-banner'),p=x.prank;banner.hidden=!p;banner.textContent=p?.kind==='chief'?'👑 Elio ist gerade Stream-Chef!':p?.kind==='vault-alarm'?'🚨 Fehlalarm! Elio bewacht den Tresor.':'';const hint=document.querySelector('#personality-hint');hint.hidden=!x.obsHint;hint.textContent=x.obsHint?.message||'';`:
    type==='drop'?`const d=x.drop;if(!x.visible||!d){root.hidden=true;return}root.hidden=false;document.querySelector('#title').textContent=d.status==='completed'?'KISTE GEÖFFNET!':d.rarityLabel;document.querySelector('#info').textContent=d.status==='completed'?(d.result.participants===0?'Diesmal war niemand dabei':d.result.participants+' Teilnehmende · je '+d.result.rewardXp+' XP'):d.participants+' dabei · '+Math.max(0,Math.ceil((d.endsAt-Date.now())/1000))+'s';root.dataset.anim=d.status;`:
      `const d=x.wheel;if(!x.visible||!d){root.hidden=true;return}root.hidden=false;document.querySelector('#title').textContent=d.status==='spinning'?'DAS RAD DREHT…':d.status==='active'?'CHALLENGE LÄUFT':'ERGEBNIS';document.querySelector('#info').textContent=d.status==='active'?(d.wheelKey==='no_jumping'?d.title+' · Janniks Aufgabe; Abschluss nicht automatisch prüfbar':d.title+' · noch '+Math.max(0,Math.ceil((d.endsAt-Date.now())/1000))+' Sekunden'):d.title;root.dataset.anim=d.status;`;
  return `<!doctype html><html lang="de"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="no-referrer"><title>${title}</title><style nonce="${nonce}">*{box-sizing:border-box}html,body{margin:0;background:transparent;color:#fff;font:700 clamp(18px,3vw,38px) system-ui;text-align:center}.card{padding:18px;border:2px solid #ba86ff;border-radius:24px;background:linear-gradient(135deg,#171522ed,#302244d9);box-shadow:0 8px 30px #0008;width:min(94vw,620px);animation:appear .5s ease}h1{font-size:.9em;margin:.2em}p{font-size:.55em;color:#e2d7f5;margin:.2em}.cat,.chest,.wheel{font-size:2.1em;filter:drop-shadow(0 0 14px #ba86ff)}#root[data-anim=feed] .cat{animation:bop .5s infinite alternate}#root[data-anim=play] .cat,#root[data-anim=happy] .cat{animation:bop .35s infinite alternate}#root[data-anim=evolution] .cat,#root[data-anim=levelup] .cat{animation:glow 1s infinite alternate}#root[data-anim=spinning] .wheel{animation:spin 2s cubic-bezier(.2,.8,.2,1)}[hidden]{display:none!important}#personality-hint{margin:.5em auto 0;padding:.45em .8em;border:1px solid #8464a8;border-radius:12px;background:#241d32;color:#f1deff;font-size:.45em;max-width:32em}#root[data-anim=surprise] .cat{animation:bop .8s 2 alternate}@keyframes appear{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}@keyframes bop{to{transform:translateY(-9px) rotate(5deg)}}@keyframes glow{to{filter:drop-shadow(0 0 28px gold);transform:scale(1.08)}}@keyframes spin{to{transform:rotate(1080deg)}}@media(prefers-reduced-motion:reduce){*{animation:none!important}}</style><main id="root" class="card" hidden>${markup}</main><script nonce="${nonce}">const root=document.querySelector('#root');let lastSnapshot;function render(x){lastSnapshot=x;${script}}function refresh(){fetch('/widgets/api/${type}'+location.search,{cache:'no-store'}).then(r=>r.json()).then(render).catch(()=>{})}const es=new EventSource('/widgets/stream/${type}'+location.search);es.addEventListener('snapshot',e=>{try{render(JSON.parse(e.data))}catch{}});es.onopen=refresh;refresh();setInterval(refresh,30000);setInterval(()=>{if(lastSnapshot)render(lastSnapshot)},1000);</script></html>`;
}

function wheelWidgetHtml(nonce:string):string {
  const markup=`<main id="root" class="card" hidden aria-live="polite"><header>ACY · CHAOS WHEEL</header><div class="stage"><svg id="wheel" viewBox="0 0 500 500" role="img" aria-label="Chaos Wheel mit gewichteten Segmenten"><g id="rotor"></g><path class="pointer" d="M250 3 L231 39 L269 39 Z"/><circle class="hub" cx="250" cy="250" r="27"/></svg></div><h1 id="title">Das Ergebnis steht fest</h1><p id="info">Das Backend hat die Aktion bereits ausgelöst. Das Rad zeigt dieses Ergebnis.</p><p id="winner" aria-live="polite"></p><p id="legend" class="legend"></p></main>`;
  return `<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="no-referrer"><title>ACY · Chaos Wheel</title><style nonce="${nonce}">
*{box-sizing:border-box}html,body{margin:0;width:100%;min-height:100%;background:transparent;color:#fff;font-family:system-ui,-apple-system,sans-serif;text-align:center}.card{position:relative;width:min(94vw,560px);margin:auto;padding:14px 20px 18px;border:1px solid #ad73f3;border-radius:24px;background:linear-gradient(145deg,rgba(18,16,30,.96),rgba(38,23,52,.92));box-shadow:0 8px 30px #0008,0 0 22px #a04aff35;opacity:0;transform:translateY(10px) scale(.98);transition:opacity .35s ease,transform .35s ease}.card.show{opacity:1;transform:none}header{color:#d8b7ff;font-weight:850;letter-spacing:.16em;font-size:clamp(13px,2vw,18px)}.stage{position:relative;width:min(72vw,420px);margin:4px auto 0;filter:drop-shadow(0 7px 14px #0009)}svg{display:block;width:100%;overflow:visible}#rotor{transform-origin:250px 250px;will-change:transform}.segment{stroke:#17121f;stroke-width:2}.segment-label{fill:#fff;font-size:15px;font-weight:800;text-anchor:middle;dominant-baseline:middle;paint-order:stroke;stroke:#17121f;stroke-width:3px;stroke-linejoin:round}.pointer{fill:#fff2a6;stroke:#301643;stroke-width:5;filter:drop-shadow(0 2px 4px #000)}.hub{fill:#21172c;stroke:#f2dcff;stroke-width:5}h1{font-size:clamp(20px,4vw,30px);margin:3px 0 0;text-shadow:0 2px 8px #000}p{font-size:clamp(12px,2.4vw,16px);color:#e0d6eb;margin:3px 0}.legend{max-width:480px;margin:5px auto 0;font-size:11px;color:#c8bdd4}.winner{filter:drop-shadow(0 0 11px #fff36a)}[hidden]{display:none!important}@keyframes pulse{50%{filter:drop-shadow(0 0 18px #f6dc72)}}@keyframes sparkle{0%{opacity:0;transform:translateY(8px) scale(.8)}35%{opacity:1;transform:translateY(-8px) scale(1.1)}100%{opacity:0;transform:translateY(-20px) scale(1)}}.card.result .hub{animation:pulse .8s 2 alternate}.card.result #winner{color:#fff2a6;font-weight:900;text-shadow:0 0 14px #fff36a}.card.result::after{content:"✨  🎉  ✨";position:absolute;inset:42% 0 auto;font-size:clamp(22px,5vw,40px);pointer-events:none;animation:sparkle 1.8s ease-out 2}@media(max-width:480px){.card{padding:10px}.stage{width:min(76vw,360px)}}@media(prefers-reduced-motion:reduce){*,*::before,*::after{transition:none!important;animation:none!important;scroll-behavior:auto!important}}
</style></head><body>${markup}<script nonce="${nonce}">
const root=document.querySelector('#root'),svg=document.querySelector('#wheel'),rotor=document.querySelector('#rotor'),colors=['#7938b9','#b73589','#4d59b8','#cf633f','#298c88','#9a3b56','#5b6e2b','#7550a0','#bd7b2f','#476c9e'];let initialized=false,rotation=0,hideTimer,renderedSpinId='';const storageKey='acy-wheel-seen:'+location.pathname;
function point(angle,r){const a=angle*Math.PI/180;return [250+Math.cos(a)*r,250+Math.sin(a)*r]}
function build(fields){rotor.replaceChildren();const valid=fields.filter(f=>Number.isFinite(f.weight)&&f.weight>0),total=valid.reduce((s,f)=>s+f.weight,0);if(!total)return [];let angle=-90;const segments=[];for(let i=0;i<valid.length;i++){const f=valid[i],start=angle;angle+=360*f.weight/total;const end=angle,center=(start+end)/2,[sx,sy]=point(start,220),[ex,ey]=point(end,220),large=end-start>180?1:0,path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d','M 250 250 L '+sx+' '+sy+' A 220 220 0 '+large+' 1 '+ex+' '+ey+' Z');path.setAttribute('fill',colors[i%colors.length]);path.setAttribute('class','segment');path.setAttribute('data-field-id',f.id);path.setAttribute('data-center-angle',String(center));rotor.append(path);const [tx,ty]=point(center,143),label=document.createElementNS('http://www.w3.org/2000/svg','text');label.setAttribute('x',String(tx));label.setAttribute('y',String(ty));label.setAttribute('class','segment-label');const shortLabels={viewer_xp:'XP-Gewinn',viewer_mystery_drop:'Mystery Drop',viewer_honor:'Ehrenmoment',community_bonus:'Community-XP',quest_luck:'Quest-Glück',chaos_title:'Chaos-Magnet',extra_spin:'Zusatzdreh'};const display=shortLabels[f.wheelKey]||(f.title.length>18?f.title.trim().split(/\s+/).slice(0,2).join(' '):f.title);label.textContent=display.length>14?display.slice(0,13)+'…':display;label.setAttribute('aria-label',f.title);rotor.append(label);segments.push({...f,start,end,center})}return segments}
function levelLabels(){rotor.querySelectorAll('.segment-label').forEach(label=>{const x=Number(label.getAttribute('x')),y=Number(label.getAttribute('y'));label.setAttribute('transform','rotate('+(-rotation)+' '+x+' '+y+')')})}
function showResult(d,animate){clearTimeout(hideTimer);root.hidden=false;root.dataset.spinId=d.id||'';renderedSpinId=d.id||'';requestAnimationFrame(()=>root.classList.add('show'));root.classList.remove('result');const title=document.querySelector('#title'),info=document.querySelector('#info'),winner=document.querySelector('#winner'),legend=document.querySelector('#legend');title.textContent=d.status==='active'?'AKTION LÄUFT':'ERGEBNIS';info.textContent='Das Ergebnis steht fest. Das Rad zeigt die bereits ausgelöste Aktion.';const resultLabel=d.resultLabel||d.title||'';winner.textContent=d.winnerName?(resultLabel.startsWith('@'+d.winnerName)?resultLabel:'@'+d.winnerName+' · '+resultLabel):resultLabel;const segments=build(d.fields||[]);legend.textContent=segments.length+' gewichtete Felder · Segmentgrößen entsprechen den Auswahlgewichten';rotor.querySelectorAll('.winner').forEach(x=>x.classList.remove('winner'));const selected=segments.find(s=>s.id===d.selectedKey);if(selected){const paths=rotor.querySelectorAll('.segment');const index=segments.indexOf(selected);paths[index]?.classList.add('winner');svg.dataset.selectedKey=d.selectedKey;svg.dataset.selectedCenter=String(selected.center);const align=(( -90-selected.center-rotation)%360+360)%360;if(animate){const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const target=rotation+align+6*360;if(reduced){rotation=target;rotor.style.transform='rotate('+rotation+'deg)';levelLabels();root.classList.add('result')}else{const from=rotation;rotation=target;rotor.animate([{transform:'rotate('+from+'deg)'},{transform:'rotate('+target+'deg)'}],{duration:6000,easing:'cubic-bezier(.10,.02,.12,1)',fill:'forwards'}).onfinish=()=>{levelLabels();root.classList.add('result')}}}else{rotation+=align;rotor.style.transform='rotate('+rotation+'deg)';levelLabels();root.classList.add('result')}}hideTimer=setTimeout(()=>{root.classList.remove('show');setTimeout(()=>root.hidden=true,400)},d.rewardStatus==='cosmetic'?60000:9000)}
function render(x){const d=x?.wheel;if(!x?.visible||!d){if(!initialized){root.hidden=true;return}return}const id=String(d.id||'');if(id&&id===renderedSpinId)return;let seen=[];try{seen=JSON.parse(sessionStorage.getItem(storageKey)||'[]')}catch{}const alreadySeen=!id||seen.includes(id);if(id&&!alreadySeen){seen=[...seen,id].slice(-50);try{sessionStorage.setItem(storageKey,JSON.stringify(seen))}catch{}}if(!initialized||alreadySeen||d.status==='canceled'){initialized=true;showResult(d,false);if(d.status==='canceled')document.querySelector('#title').textContent='DREH ABGEBROCHEN';return}initialized=true;showResult(d,true)}
async function baseline(){try{const r=await fetch('/widgets/api/wheel'+location.search,{cache:'no-store'});if(r.ok)render(await r.json())}catch{}initialized=true;root.dataset.ready='true';connect()}function connect(){const events=new EventSource('/widgets/stream/wheel'+location.search);events.addEventListener('snapshot',e=>{try{render(JSON.parse(e.data))}catch{}});events.onopen=()=>{};window.addEventListener('online',()=>{if(events.readyState===EventSource.CLOSED)connect()},{once:true})}baseline();
</script></body></html>`;
}
